 v=regions.setdefault(r["区域"],[0,Decimal(0)]); v[0]+=1; v[1]+=a
with zipfile.ZipFile("deliverables/销售核对.xlsx") as z:
 wb=E.fromstring(z.read("xl/workbook.xml")); targets={r.get("Id"):r.get("Target") for r in E.fromstring(z.read("xl/_rels/workbook.xml.rels"))}; sheets=[]
