  target=targets[s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")]; path=target.lstrip("/") if target.startswith("/") else posixpath.normpath(posixpath.join("xl",target)); root=E.fromstring(z.read(path)); cells={}
  for c in root.findall("s:sheetData/s:row/s:c",ns):
   assert c.find("s:f",ns) is None; t=c.get("t","n"); v=c.find("s:v",ns); raw=v.text if v is not None else None; assert t in ("str","n","b"),(c.get("r"),t); value=Decimal(raw) if t=="n" else (raw=="1" if t=="b" else raw); cells[c.get("r")]=(t,value)
  sheets.append((s.get("name"),cells)); print(s.get("name"),"nonempty=",len(cells),"types=",dict(collections.Counter(t for t,v in cells.values())))
 assert [n for n,c in sheets]==["订单明细","区域汇总","统计说明"]
 detail=sheets[0][1]; expected={k+"1":("str",v) for k,v in zip("ABCDEF",["原行序","订单编号","区域","金额","备注","退款"])}
 for i,(r,a) in enumerate(zip(rows,amounts),2):
  for k,t,v in zip("ABCDEF",["n","str","str","n","str","b"],[Decimal(i-1),r["订单编号"],r["区域"],a,r["备注"],a<0]): expected[k+str(i)]=(t,v)
 assert detail==expected,"detail discrepancy"
 expected={k+"1":("str",v) for k,v in zip("ABC",["区域","订单数","净金额"])}
 for i,(name,(count,amount)) in enumerate(list(regions.items())+[("全体合计",[len(rows),sum(amounts)])],2):
  expected.update({"A"+str(i):("str",name),"B"+str(i):("n",Decimal(count)),"C"+str(i):("n",amount)})
 assert sheets[1][1]==expected,"region discrepancy"
 stats=sheets[2][1]; values={12:len(rows),13:sum(amounts),14:sum(a<0 for a in amounts),15:sum(a for a in amounts if a<0),16:sum(a==0 for a in amounts),17:sum(a for a in amounts if a==0),18:sum(a>0 for a in amounts),19:sum(a for a in amounts if a>0)}
 for row,value in values.items(): assert stats["B"+str(row)]==("n",Decimal(value)),row
 assert len(stats)==56 and all(stats["A"+str(i)][0]=="str" for i in range(1,29)); assert all(stats["B"+str(i)][0]=="str" for i in range(1,29) if i not in values)
 external=[]
 for name in z.namelist():
  if name.endswith(".rels"):
   external.extend((name,r.get("Target")) for r in E.fromstring(z.read(name)) if r.get("TargetMode")=="External")
 assert not external,external; print("PASS: sheet order; every detail and regional cell address/type/value; 8 numeric statistics; all 104 nonempty cell types; no formulas or external relationships.")'

